import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

// Generates the two modules compiled into the `pigeon` binary:
//   src/server/embedded-html.ts — the single-file PWA from `vite build`
//   src/server/pwa-assets.ts    — manifest, service worker and icons from public/
// public/ is the only source for the PWA assets; never edit the generated files.

const rootDir = join(import.meta.dir, "..");
const pub = (name: string) => join(rootDir, "public", name);

const distHtmlPath = join(rootDir, "dist", "index.html");
if (!existsSync(distHtmlPath)) {
  console.error("dist/index.html not found; run `vite build` first");
  process.exit(1);
}
const html = readFileSync(distHtmlPath, "utf-8");
writeFileSync(
  join(rootDir, "src", "server", "embedded-html.ts"),
  `// Auto-generated by scripts/embed-html.ts - DO NOT EDIT MANUALLY\nexport const EMBEDDED_HTML = ${JSON.stringify(html)};\n`
);

const assets = [
  "// Auto-generated by scripts/embed-html.ts from public/ - DO NOT EDIT MANUALLY",
  `export const PWA_MANIFEST = ${JSON.stringify(JSON.parse(readFileSync(pub("manifest.webmanifest"), "utf-8")), null, 2)};`,
  `export const PWA_SW_SCRIPT = ${JSON.stringify(readFileSync(pub("sw.js"), "utf-8"))};`,
  `export const PWA_ICON_SVG = ${JSON.stringify(readFileSync(pub("icon.svg"), "utf-8"))};`,
  `export const PWA_ICON_192_BASE64 = ${JSON.stringify(readFileSync(pub("icon-192.png")).toString("base64"))};`,
  `export const PWA_ICON_512_BASE64 = ${JSON.stringify(readFileSync(pub("icon-512.png")).toString("base64"))};`,
];
writeFileSync(join(rootDir, "src", "server", "pwa-assets.ts"), assets.join("\n\n") + "\n");
console.log("Embedded dist/index.html and public/ PWA assets");
